// Generated by `php artisan platform:embed-openapi` from docs/openapi.yaml. Do not edit.
window.OPENAPI_YAML = "openapi: 3.1.0\r\ninfo:\r\n  title: Dating Platform mobile API\r\n  version: \"1\"\r\n  summary: The /api/v1 surface the mobile app uses, derived from routes/api.php and app/Http/Resources/Api/V1.\r\n  description: |\r\n    Every endpoint the mobile client calls. The website does not use this API; both clients call the same\r\n    services underneath, so a rule changed in the console applies identically to both.\r\n\r\n    **Authentication.** A Sanctum bearer token from `POST /auth/register` or `POST /auth/login`. Tokens carry\r\n    **abilities** set at issue time: a `pending` member's token has `profile:read`, `profile:write` and `verify`\r\n    only; an `active` member's token has those plus `swipe`, `message` and `report`. The existing token is\r\n    **not** upgraded when the account is promoted — the app must sign in again to get a full token\r\n    (`AuthController::abilitiesFor`).\r\n\r\n    **Pagination.** Every list is cursor-paginated: `{data, meta.next_cursor}`. Pass `?cursor=` to get the\r\n    next page; `null` means the end. There are no page numbers.\r\n\r\n    **Errors.** One envelope everywhere: `{message, code, errors?}`. Branch on `code`, never on the message.\r\n    Codes: `unauthenticated` (401), `forbidden`, `account_restricted`, `account_deactivated`, `premium_required`\r\n    (403), `not_found` (404), `validation_failed`, `photo_limit_reached`, `verification_attempts_exhausted`,\r\n    `product_unknown`, `receipt_invalid` (422), `receipt_owned_elsewhere` (409), `rate_limited` (429, with\r\n    `Retry-After`), `maintenance`, `sms_unavailable`, `store_unavailable` (503), `server_error` (500).\r\n\r\n    **Throttling.** `x-throttle` on each operation names the bucket (app/Providers/PlatformServiceProvider.php):\r\n    `api` 90/min · `deck` 60/min · `swipe` 120/min · `message` 30/min · `report` 10/hour · `verification` 3/day ·\r\n    `receipt` 10/hour · `auth` 8/min per IP and 5/min per IP+email · phone `4,10` = 4 per 10 min, `10,10` = 10\r\n    per 10 min. Limits are settings and can be tightened without a deploy. Accounts under 24 hours old get half\r\n    of the `swipe` and `message` allowances.\r\n\r\n    **Restricted accounts.** Every authenticated route passes `appuser.active`: a suspended or banned member gets\r\n    `403 account_restricted` with a `restriction` object; a deactivated one `403 account_deactivated`. A\r\n    shadow-banned member is reported as `active` and refused nothing.\r\n\r\n    **Maintenance.** When maintenance mode is on, every route answers `503 maintenance` with `Retry-After`.\r\n  x-token-abilities:\r\n    pending: [profile:read, profile:write, verify]\r\n    active: [profile:read, profile:write, swipe, message, report, verify]\r\n\r\nservers:\r\n  - url: /api/v1\r\n    description: Relative to the site root, e.g. https://example.com/api/v1\r\n\r\ntags:\r\n  - name: Public\r\n    description: No token. Reference data and the launch config.\r\n  - name: Auth\r\n  - name: Me\r\n    description: The signed-in member's own account, profile, preferences and interests.\r\n  - name: Photos\r\n    description: Need `profile:write`, which a pending token carries, so onboarding can finish in the app.\r\n  - name: Discovery\r\n  - name: Matches\r\n  - name: Conversations\r\n  - name: Safety\r\n  - name: Phone\r\n  - name: Devices\r\n  - name: Verification\r\n  - name: Premium\r\n\r\ncomponents:\r\n  securitySchemes:\r\n    bearerAuth:\r\n      type: http\r\n      scheme: bearer\r\n      description: Sanctum personal access token from /auth/register or /auth/login.\r\n\r\n  parameters:\r\n    cursor:\r\n      name: cursor\r\n      in: query\r\n      required: false\r\n      schema: { type: string }\r\n      description: The `meta.next_cursor` of the previous page. Omit for the first page.\r\n\r\n  responses:\r\n    Unauthenticated:\r\n      description: No token, or a revoked one. `code` is `unauthenticated`; the app signs out.\r\n      content: { application/json: { schema: { $ref: \"#/components/schemas/Error\" }, example: { message: \"Sign in to continue.\", code: unauthenticated } } }\r\n    Forbidden:\r\n      description: |\r\n        `forbidden` — the token lacks the ability (a pending member) or the record is not yours.\r\n        `account_restricted` — suspended or banned; carries `restriction`. `account_deactivated` — the member deactivated the account.\r\n      content:\r\n        application/json:\r\n          schema: { $ref: \"#/components/schemas/Error\" }\r\n          examples:\r\n            forbidden: { value: { message: \"Not permitted.\", code: forbidden } }\r\n            restricted: { value: { message: \"Your account is suspended until 2026-10-01.\", code: account_restricted, restriction: { type: suspension, expires_at: \"2026-10-01T00:00:00+00:00\", policy_clause: \"3.2\", appealable: true } } }\r\n            deactivated: { value: { message: \"This account is deactivated.\", code: account_deactivated } }\r\n    NotFound:\r\n      description: No such record, or not one you may see (records are never revealed by a 403 where a 404 will do).\r\n      content: { application/json: { schema: { $ref: \"#/components/schemas/Error\" }, example: { message: \"Not found.\", code: not_found } } }\r\n    ValidationFailed:\r\n      description: \"`validation_failed`, with `errors` keyed by field.\"\r\n      content: { application/json: { schema: { $ref: \"#/components/schemas/Error\" }, example: { message: \"The given data was invalid.\", code: validation_failed, errors: { city_id: [\"That city is not available right now. Choose another.\"] } } } }\r\n    RateLimited:\r\n      description: \"`rate_limited`. `Retry-After` says how many seconds to wait; the app shows a strip, not an error.\"\r\n      headers: { Retry-After: { schema: { type: integer }, description: \"Seconds until the bucket refills.\" } }\r\n      content: { application/json: { schema: { $ref: \"#/components/schemas/Error\" }, example: { message: \"Too many requests. Slow down.\", code: rate_limited } } }\r\n    Maintenance:\r\n      description: \"`maintenance` — the operator switched maintenance mode on. Every route answers this until it is off.\"\r\n      headers: { Retry-After: { schema: { type: integer } } }\r\n      content: { application/json: { schema: { $ref: \"#/components/schemas/Error\" }, example: { message: \"We are down for maintenance.\", code: maintenance } } }\r\n\r\n  schemas:\r\n    Error:\r\n      type: object\r\n      required: [message, code]\r\n      properties:\r\n        message: { type: string, description: \"For a person. Never branch on it.\" }\r\n        code: { type: string, description: \"The machine-readable reason. Branch on this.\" }\r\n        errors: { type: object, additionalProperties: { type: array, items: { type: string } }, description: \"Field errors, on validation_failed only.\" }\r\n        restriction: { $ref: \"#/components/schemas/Restriction\" }\r\n        count: { type: integer, description: \"On premium_required from /me/likers — how many people liked you.\" }\r\n        limit: { type: integer, description: \"On photo_limit_reached — the operator's photo cap.\" }\r\n    Restriction:\r\n      type: object\r\n      description: Sent with 403 account_restricted.\r\n      properties:\r\n        type: { type: [string, \"null\"], enum: [feature_limit, shadow_ban, suspension, permanent_ban, device_ban, null] }\r\n        expires_at: { type: [string, \"null\"], format: date-time }\r\n        policy_clause: { type: [string, \"null\"] }\r\n        appealable: { type: boolean }\r\n    CursorMeta:\r\n      type: object\r\n      required: [next_cursor]\r\n      properties:\r\n        next_cursor: { type: [string, \"null\"], description: \"Pass as ?cursor= for the next page; null at the end.\" }\r\n    Gender:\r\n      type: string\r\n      enum: [woman, man, non_binary, other]\r\n    ReportCategory:\r\n      type: string\r\n      enum: [harassment, sexual_content, nudity, fake_profile, impersonation, scam_fraud, spam_promotion, off_platform_solicitation, prostitution, hate_speech, violence_threats, self_harm, underage_suspected, minor_safety, other]\r\n    Photo:\r\n      type: object\r\n      description: PhotoResource. `moderation_status` appears only on your own photos.\r\n      required: [id, url, thumb_url, position, is_primary]\r\n      properties:\r\n        id: { type: string, format: uuid }\r\n        url: { type: string, format: uri }\r\n        thumb_url: { type: string, format: uri }\r\n        position: { type: integer }\r\n        is_primary: { type: boolean }\r\n        moderation_status: { type: string, enum: [pending, approved, auto_flagged, rejected], description: \"Own photos only. Pending photos are still shown to others — there is no proactive review queue.\" }\r\n    Profile:\r\n      type: object\r\n      description: ProfileResource. Option keys (education, relationship_goal, drinking, smoking, children) come from the console's Profile questions master; there is no endpoint for the labels.\r\n      properties:\r\n        bio: { type: [string, \"null\"], maxLength: 500 }\r\n        height_cm: { type: [integer, \"null\"], minimum: 100, maximum: 250 }\r\n        job_title: { type: [string, \"null\"], maxLength: 100 }\r\n        company: { type: [string, \"null\"], maxLength: 100 }\r\n        school: { type: [string, \"null\"], maxLength: 100 }\r\n        education: { type: [string, \"null\"] }\r\n        relationship_goal: { type: [string, \"null\"] }\r\n        drinking: { type: [string, \"null\"] }\r\n        smoking: { type: [string, \"null\"] }\r\n        children: { type: [string, \"null\"] }\r\n        languages: { type: array, items: { type: string } }\r\n        prompts: { type: array, items: { type: object } }\r\n    Preferences:\r\n      type: object\r\n      description: PreferenceResource.\r\n      required: [interested_in, age_min, age_max, max_distance_km, global_mode, show_verified_only]\r\n      properties:\r\n        interested_in: { type: array, items: { $ref: \"#/components/schemas/Gender\" } }\r\n        age_min: { type: integer }\r\n        age_max: { type: integer }\r\n        max_distance_km: { type: [integer, \"null\"] }\r\n        global_mode: { type: boolean }\r\n        show_verified_only: { type: boolean }\r\n    Me:\r\n      type: object\r\n      description: MeResource — the signed-in member. A shadow ban is reported as `active` by design.\r\n      required: [id, display_name, email, account_status, verification_status, is_premium, profile_completion, restrictions]\r\n      properties:\r\n        id: { type: string, format: uuid }\r\n        display_name: { type: string }\r\n        email: { type: string, format: email }\r\n        phone: { type: [string, \"null\"] }\r\n        birthdate: { type: [string, \"null\"], format: date }\r\n        age: { type: [integer, \"null\"] }\r\n        gender: { oneOf: [{ $ref: \"#/components/schemas/Gender\" }, { type: \"null\" }] }\r\n        pronouns: { type: [string, \"null\"] }\r\n        account_status: { type: string, enum: [active, pending, limited, suspended, banned, deactivated], description: \"pending until the profile is at least half complete; then the token must be re-issued.\" }\r\n        verification_status: { type: string, enum: [unverified, pending, in_review, approved, rejected, escalated, expired] }\r\n        is_premium: { type: boolean, description: \"The only source of entitlement the app may trust.\" }\r\n        premium_tier: { type: [string, \"null\"], description: \"Plan slug.\" }\r\n        premium_until: { type: [string, \"null\"], format: date-time }\r\n        premium_source: { type: [string, \"null\"], enum: [manual, payment, apple, google, null], description: \"Where the plan came from decides where it is managed.\" }\r\n        auto_renewing: { type: [boolean, \"null\"], description: \"The store's word; null for anything not from a store.\" }\r\n        profile_completion: { type: integer, minimum: 0, maximum: 100 }\r\n        city: { type: [object, \"null\"], properties: { name: { type: string }, state: { type: [string, \"null\"] }, country: { type: [string, \"null\"], description: \"ISO 3166-1 alpha-2\" } } }\r\n        restrictions: { type: array, items: { type: string }, description: \"Feature keys switched off by a feature limit.\" }\r\n        profile: { $ref: \"#/components/schemas/Profile\" }\r\n        preferences: { $ref: \"#/components/schemas/Preferences\" }\r\n        photos: { type: array, items: { $ref: \"#/components/schemas/Photo\" } }\r\n        interests: { type: array, items: { type: string }, description: \"Interest names.\" }\r\n        created_at: { type: [string, \"null\"], format: date-time }\r\n    Person:\r\n      type: object\r\n      description: AppUserResource — another member. Never their email, phone, birthdate, coordinates, risk or report counts.\r\n      required: [id, display_name, is_verified]\r\n      properties:\r\n        id: { type: string, format: uuid }\r\n        display_name: { type: string }\r\n        age: { type: [integer, \"null\"] }\r\n        gender: { oneOf: [{ $ref: \"#/components/schemas/Gender\" }, { type: \"null\" }] }\r\n        pronouns: { type: [string, \"null\"] }\r\n        is_verified: { type: boolean }\r\n        city: { type: [string, \"null\"] }\r\n        distance_km: { type: integer, description: \"Bucketed to whole kilometres; present only when both have coordinates.\" }\r\n        photos: { type: array, items: { $ref: \"#/components/schemas/Photo\" } }\r\n        profile: { $ref: \"#/components/schemas/Profile\" }\r\n        interests: { type: array, items: { type: string } }\r\n    Match:\r\n      type: object\r\n      description: MatchResource.\r\n      required: [id, status, other, messages_count, has_conversation]\r\n      properties:\r\n        id: { type: string, format: uuid }\r\n        matched_at: { type: [string, \"null\"], format: date-time }\r\n        status: { type: string, enum: [active, unmatched, blocked, expired] }\r\n        other: { oneOf: [{ $ref: \"#/components/schemas/Person\" }, { type: \"null\" }] }\r\n        last_message_at: { type: [string, \"null\"], format: date-time }\r\n        messages_count: { type: integer }\r\n        has_conversation: { type: boolean }\r\n    Conversation:\r\n      type: object\r\n      description: ConversationResource. Lists contain open threads only; a block or unmatch closes one.\r\n      required: [id, other, messages_count, status]\r\n      properties:\r\n        id: { type: string, format: uuid }\r\n        other: { oneOf: [{ $ref: \"#/components/schemas/Person\" }, { type: \"null\" }] }\r\n        messages_count: { type: integer }\r\n        last_message_at: { type: [string, \"null\"], format: date-time }\r\n        started_at: { type: [string, \"null\"], format: date-time }\r\n        status: { type: string, enum: [open, closed, frozen] }\r\n    Message:\r\n      type: object\r\n      description: MessageResource. `body` is null when `removed`.\r\n      required: [id, type, body, removed, is_mine]\r\n      properties:\r\n        id: { type: string, format: uuid }\r\n        type: { type: string, enum: [text, image, gif, voice, system] }\r\n        body: { type: [string, \"null\"] }\r\n        removed: { type: boolean, description: \"Removed by moderation.\" }\r\n        media_url: { type: [string, \"null\"], format: uri }\r\n        is_mine: { type: boolean }\r\n        read_at: { type: [string, \"null\"], format: date-time }\r\n        sent_at: { type: [string, \"null\"], format: date-time }\r\n    Verification:\r\n      type: object\r\n      description: VerificationResource — the member's latest selfie verification.\r\n      required: [id, status, attempts_used, attempts_remaining]\r\n      properties:\r\n        id: { type: string, format: uuid }\r\n        status: { type: string, enum: [pending, in_review, approved, rejected, escalated, expired] }\r\n        submitted_at: { type: [string, \"null\"], format: date-time }\r\n        attempts_used: { type: integer }\r\n        attempts_remaining: { type: integer, description: \"Out of verification.max_attempts (3).\" }\r\n        rejection_reason: { type: [string, \"null\"], description: \"The enumerated reason's label, after a rejection.\" }\r\n    Config:\r\n      type: object\r\n      required: [min_supported_version, maintenance_mode, min_age, max_photos, max_distance_km, daily_like_limit, appeal_window_days]\r\n      properties:\r\n        min_supported_version: { type: string, description: \"Semver. An older app shows the update screen.\" }\r\n        maintenance_mode: { type: boolean }\r\n        min_age: { type: integer }\r\n        max_photos: { type: integer }\r\n        max_distance_km: { type: integer }\r\n        daily_like_limit: { type: integer, description: \"For the free plan. Premium with unlimited_likes has none.\" }\r\n        appeal_window_days: { type: integer }\r\n        support_email: { type: [string, \"null\"] }\r\n    Plan:\r\n      type: object\r\n      required: [slug, name, features, perks, is_featured, products]\r\n      properties:\r\n        slug: { type: string }\r\n        name: { type: string }\r\n        tagline: { type: [string, \"null\"] }\r\n        features: { type: array, items: { type: string, enum: [unlimited_likes, see_likers, profile_badge, priority_support] } }\r\n        perks: { type: array, items: { type: string } }\r\n        is_featured: { type: boolean }\r\n        products:\r\n          type: object\r\n          description: Store product identifiers to ask StoreKit / Play Billing for. A period is omitted when not sold in that store. Prices come from the stores.\r\n          properties:\r\n            ios: { type: object, properties: { monthly: { type: string }, yearly: { type: string } } }\r\n            android: { type: object, properties: { monthly: { type: string }, yearly: { type: string } } }\r\n    Interest:\r\n      type: object\r\n      required: [slug, name, category]\r\n      properties: { slug: { type: string }, name: { type: string }, category: { type: string } }\r\n    Country:\r\n      type: object\r\n      required: [iso2, name]\r\n      properties: { iso2: { type: string, minLength: 2, maxLength: 2 }, name: { type: string }, dial_code: { type: [string, \"null\"] } }\r\n    State:\r\n      type: object\r\n      required: [id, name, country_id]\r\n      properties: { id: { type: integer }, name: { type: string }, code: { type: [string, \"null\"] }, country_id: { type: integer } }\r\n    City:\r\n      type: object\r\n      required: [id, name, country_id]\r\n      properties: { id: { type: integer }, name: { type: string }, country_id: { type: integer }, state: { type: [string, \"null\"] }, state_id: { type: [integer, \"null\"] } }\r\n    AuthResponse:\r\n      type: object\r\n      required: [token, user]\r\n      properties:\r\n        token: { type: string, description: \"Store in secure storage. Abilities depend on user.account_status at issue time.\" }\r\n        user: { $ref: \"#/components/schemas/Me\" }\r\n    SwipeResponse:\r\n      type: object\r\n      required: [is_match, match]\r\n      properties:\r\n        is_match: { type: boolean }\r\n        match: { oneOf: [{ $ref: \"#/components/schemas/Match\" }, { type: \"null\" }] }\r\n\r\npaths:\r\n  # ---- Public ---------------------------------------------------------------------\r\n  /config:\r\n    get:\r\n      tags: [Public]\r\n      summary: Launch configuration\r\n      description: Read on every launch. Nothing here is hard-coded in the app.\r\n      operationId: getConfig\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { $ref: \"#/components/schemas/Config\" } } } }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /plans:\r\n    get:\r\n      tags: [Public, Premium]\r\n      summary: Plans on sale, with store product ids\r\n      operationId: listPlans\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { data: { type: array, items: { $ref: \"#/components/schemas/Plan\" } } } } } } }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /interests:\r\n    get:\r\n      tags: [Public]\r\n      summary: Interests a member can pick\r\n      operationId: listInterests\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { data: { type: array, items: { $ref: \"#/components/schemas/Interest\" } } } } } } }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /countries:\r\n    get:\r\n      tags: [Public]\r\n      summary: Countries that are shown at sign-up\r\n      operationId: listCountries\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { data: { type: array, items: { $ref: \"#/components/schemas/Country\" } } } } } } }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /states:\r\n    get:\r\n      tags: [Public]\r\n      summary: States of a country that are shown at sign-up\r\n      operationId: listStates\r\n      parameters:\r\n        - { name: country, in: query, schema: { type: string, minLength: 2, maxLength: 2 }, description: \"ISO 3166-1 alpha-2. Omit for every country.\" }\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { data: { type: array, items: { $ref: \"#/components/schemas/State\" } } } } } } }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /cities:\r\n    get:\r\n      tags: [Public]\r\n      summary: City search (type-ahead)\r\n      description: |\r\n        A search, not a list. `search` matches the start of the name and must be two characters or more\r\n        (one character is `422 validation_failed`). At most 100 rows come back; `meta.truncated` says whether\r\n        there were more, so the app asks the member to keep typing. Only cities that may be chosen right now —\r\n        city, state and country all shown — are returned, the same rule the write paths apply.\r\n      operationId: searchCities\r\n      parameters:\r\n        - { name: search, in: query, schema: { type: string, minLength: 2, maxLength: 80 }, description: \"Start of the city name, two characters or more.\" }\r\n        - { name: country, in: query, schema: { type: string, minLength: 2, maxLength: 2 } }\r\n        - { name: state, in: query, schema: { type: integer }, description: \"A state id from /states.\" }\r\n      responses:\r\n        \"200\":\r\n          description: OK\r\n          content:\r\n            application/json:\r\n              schema:\r\n                type: object\r\n                properties:\r\n                  data: { type: array, items: { $ref: \"#/components/schemas/City\" } }\r\n                  meta: { type: object, properties: { limit: { type: integer, example: 100 }, truncated: { type: boolean } } }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n\r\n  # ---- Auth -----------------------------------------------------------------------\r\n  /auth/register:\r\n    post:\r\n      tags: [Auth]\r\n      summary: Create an account\r\n      description: The account starts `pending`; the token carries only `profile:read`, `profile:write` and `verify` until the profile is at least half complete and the app signs in again. `city_id` is optional here — onboarding asks — but must be a selectable city.\r\n      operationId: register\r\n      x-throttle: auth\r\n      requestBody:\r\n        required: true\r\n        content:\r\n          application/json:\r\n            schema:\r\n              type: object\r\n              required: [display_name, email, password, birthdate, gender, interested_in]\r\n              properties:\r\n                display_name: { type: string, minLength: 2, maxLength: 60 }\r\n                email: { type: string, format: email }\r\n                password: { type: string, minLength: 8, description: \"Letters and numbers.\" }\r\n                birthdate: { type: string, format: date, description: \"Must make the member at least 18.\" }\r\n                gender: { $ref: \"#/components/schemas/Gender\" }\r\n                interested_in: { type: array, minItems: 1, items: { $ref: \"#/components/schemas/Gender\" } }\r\n                city_id: { type: [integer, \"null\"], description: \"A selectable city (its city, state and country all shown).\" }\r\n      responses:\r\n        \"201\": { description: \"Created\", content: { application/json: { schema: { $ref: \"#/components/schemas/AuthResponse\" } } } }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /auth/login:\r\n    post:\r\n      tags: [Auth]\r\n      summary: Sign in and get a token\r\n      description: Also how the app swaps a pending token for a full one after promotion. A suspended or banned member is refused with `403 account_restricted`; a deactivated one with `403 account_deactivated`.\r\n      operationId: login\r\n      x-throttle: auth\r\n      requestBody:\r\n        required: true\r\n        content:\r\n          application/json:\r\n            schema:\r\n              type: object\r\n              required: [email, password]\r\n              properties: { email: { type: string, format: email }, password: { type: string } }\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { $ref: \"#/components/schemas/AuthResponse\" } } } }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /auth/logout:\r\n    post:\r\n      tags: [Auth]\r\n      summary: Revoke this token\r\n      operationId: logout\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { message: { type: string } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /auth/logout-all:\r\n    post:\r\n      tags: [Auth]\r\n      summary: Revoke every token\r\n      operationId: logoutAll\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { message: { type: string } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n\r\n  # ---- Me -------------------------------------------------------------------------\r\n  /me:\r\n    get:\r\n      tags: [Me]\r\n      summary: The signed-in member\r\n      description: Re-fetched by the app after any write that could change completion. If `account_status` went pending → active, the app signs in again to swap the token.\r\n      operationId: getMe\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { data: { $ref: \"#/components/schemas/Me\" } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n    patch:\r\n      tags: [Me]\r\n      summary: Name, pronouns, city\r\n      description: \"`city_id` must be a selectable city (city, state and country all shown), except that the member's current city always passes even if it has since been hidden. Does not recompute profile completion; the city counts on the next write that does.\"\r\n      operationId: updateMe\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      requestBody:\r\n        content:\r\n          application/json:\r\n            schema:\r\n              type: object\r\n              properties:\r\n                display_name: { type: string, minLength: 2, maxLength: 60 }\r\n                pronouns: { type: [string, \"null\"], maxLength: 30 }\r\n                city_id: { type: [integer, \"null\"] }\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { data: { $ref: \"#/components/schemas/Me\" } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n    delete:\r\n      tags: [Me]\r\n      summary: Delete the account (permanent)\r\n      description: Password required. Soft-delete plus anonymisation — name, email, phone, photos and profile text are removed; messages already sent stay with their recipients; the member appears as “Deleted member” in old cases. Every token is revoked. **A store subscription is not cancelled**; only the member can, in the App Store or Google Play.\r\n      operationId: deleteMe\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      requestBody:\r\n        required: true\r\n        content: { application/json: { schema: { type: object, required: [password], properties: { password: { type: string } } } } }\r\n      responses:\r\n        \"200\": { description: \"Deleted\", content: { application/json: { schema: { type: object, properties: { message: { type: string } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /me/profile:\r\n    patch:\r\n      tags: [Me]\r\n      summary: Bio, work, education and lifestyle\r\n      description: Recomputes profile completion; the account may become active (see the token note).\r\n      operationId: updateProfile\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      requestBody:\r\n        content:\r\n          application/json:\r\n            schema:\r\n              type: object\r\n              properties:\r\n                bio: { type: [string, \"null\"], maxLength: 500 }\r\n                height_cm: { type: [integer, \"null\"], minimum: 100, maximum: 250 }\r\n                job_title: { type: [string, \"null\"], maxLength: 100 }\r\n                company: { type: [string, \"null\"], maxLength: 100 }\r\n                school: { type: [string, \"null\"], maxLength: 100 }\r\n                education: { type: [string, \"null\"], description: \"A key from the Profile questions master.\" }\r\n                relationship_goal: { type: string }\r\n                drinking: { type: string }\r\n                smoking: { type: string }\r\n                children: { type: string }\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { data: { $ref: \"#/components/schemas/Me\" } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /me/preferences:\r\n    patch:\r\n      tags: [Me]\r\n      summary: Discovery preferences\r\n      description: \"`age_min` and `age_max` are validated as a pair against what is stored: send both to move the range, or a lone value that would invert it is refused.\"\r\n      operationId: updatePreferences\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      requestBody:\r\n        content:\r\n          application/json:\r\n            schema:\r\n              type: object\r\n              properties:\r\n                interested_in: { type: array, minItems: 1, items: { $ref: \"#/components/schemas/Gender\" } }\r\n                age_min: { type: integer }\r\n                age_max: { type: integer }\r\n                max_distance_km: { type: [integer, \"null\"], description: \"Up to config.max_distance_km.\" }\r\n                global_mode: { type: boolean }\r\n                show_verified_only: { type: boolean }\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { data: { $ref: \"#/components/schemas/Me\" } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /me/interests:\r\n    put:\r\n      tags: [Me]\r\n      summary: Replace the member's interests\r\n      description: Interest slugs from /interests, up to the operator's cap. Recomputes profile completion.\r\n      operationId: syncInterests\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      requestBody:\r\n        required: true\r\n        content: { application/json: { schema: { type: object, required: [interests], properties: { interests: { type: array, items: { type: string } } } } } }\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { data: { $ref: \"#/components/schemas/Me\" } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /me/likers:\r\n    get:\r\n      tags: [Matches, Premium]\r\n      summary: Who liked you (premium)\r\n      description: Members who liked you and are still waiting for an answer. Without a plan that has `see_likers` the answer is `403 premium_required` carrying `count` — how many, never who. Entitlement is the server's decision.\r\n      operationId: listLikers\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      parameters: [{ $ref: \"#/components/parameters/cursor\" }]\r\n      responses:\r\n        \"200\":\r\n          description: OK\r\n          content:\r\n            application/json:\r\n              schema:\r\n                type: object\r\n                properties:\r\n                  data: { type: array, items: { $ref: \"#/components/schemas/Person\" } }\r\n                  meta: { allOf: [{ $ref: \"#/components/schemas/CursorMeta\" }, { type: object, properties: { count: { type: integer } } }] }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\":\r\n          description: \"`premium_required` with `count`, or the usual account refusals.\"\r\n          content: { application/json: { schema: { $ref: \"#/components/schemas/Error\" }, example: { message: \"See who liked you with Premium.\", code: premium_required, count: 12 } } }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n\r\n  # ---- Photos ---------------------------------------------------------------------\r\n  /me/photos:\r\n    post:\r\n      tags: [Photos]\r\n      summary: Upload a photo\r\n      description: Multipart. Re-encoded through GD on the server (EXIF, including GPS, is stripped). `422 photo_limit_reached` with `limit` at the operator's cap. Recomputes profile completion.\r\n      operationId: uploadPhoto\r\n      security: [{ bearerAuth: [] }]\r\n      x-ability: profile:write\r\n      x-throttle: api\r\n      requestBody:\r\n        required: true\r\n        content:\r\n          multipart/form-data:\r\n            schema: { type: object, required: [photo], properties: { photo: { type: string, format: binary, description: \"An image, JPEG/PNG/WebP.\" } } }\r\n      responses:\r\n        \"201\": { description: \"Created\", content: { application/json: { schema: { type: object, properties: { data: { $ref: \"#/components/schemas/Photo\" } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"422\":\r\n          description: \"`validation_failed`, or `photo_limit_reached` with `limit`.\"\r\n          content: { application/json: { schema: { $ref: \"#/components/schemas/Error\" }, example: { message: \"You can have up to 6 photos.\", code: photo_limit_reached, limit: 6 } } }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /me/photos/reorder:\r\n    patch:\r\n      tags: [Photos]\r\n      summary: Reorder photos\r\n      description: The full list of your photo ids in the new order — partial lists are `422`, a foreign id is `403`. Atomic.\r\n      operationId: reorderPhotos\r\n      security: [{ bearerAuth: [] }]\r\n      x-ability: profile:write\r\n      x-throttle: api\r\n      requestBody:\r\n        required: true\r\n        content: { application/json: { schema: { type: object, required: [order], properties: { order: { type: array, items: { type: string, format: uuid } } } } } }\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { data: { type: array, items: { $ref: \"#/components/schemas/Photo\" } } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /me/photos/{uuid}/primary:\r\n    patch:\r\n      tags: [Photos]\r\n      summary: Make a photo the main one\r\n      operationId: makePrimaryPhoto\r\n      security: [{ bearerAuth: [] }]\r\n      x-ability: profile:write\r\n      x-throttle: api\r\n      parameters: [{ name: uuid, in: path, required: true, schema: { type: string, format: uuid } }]\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { data: { type: array, items: { $ref: \"#/components/schemas/Photo\" } } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"404\": { $ref: \"#/components/responses/NotFound\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /me/photos/{uuid}:\r\n    delete:\r\n      tags: [Photos]\r\n      summary: Remove a photo\r\n      description: Soft-deletes the row and recomputes profile completion. `403` unless it is yours.\r\n      operationId: deletePhoto\r\n      security: [{ bearerAuth: [] }]\r\n      x-ability: profile:write\r\n      x-throttle: api\r\n      parameters: [{ name: uuid, in: path, required: true, schema: { type: string, format: uuid } }]\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { message: { type: string } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"404\": { $ref: \"#/components/responses/NotFound\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n\r\n  # ---- Discovery ------------------------------------------------------------------\r\n  /deck:\r\n    get:\r\n      tags: [Discovery]\r\n      summary: People to swipe on\r\n      description: Active members matching your preferences, excluding anyone already swiped and blocks in either direction; within your radius when you have coordinates, else your city, else anywhere. The API returns an empty deck when the area is exhausted (the website widens; the API does not). Random order without ORDER BY RAND().\r\n      operationId: getDeck\r\n      security: [{ bearerAuth: [] }]\r\n      x-ability: swipe\r\n      x-throttle: deck\r\n      parameters: [{ name: limit, in: query, schema: { type: integer, default: 20, maximum: 30 } }]\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { data: { type: array, items: { $ref: \"#/components/schemas/Person\" } }, meta: { type: object, properties: { count: { type: integer } } } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /swipes:\r\n    post:\r\n      tags: [Discovery]\r\n      summary: Like or pass\r\n      description: The server decides the outcome. A like over the free plan's daily cap is `422 validation_failed`; a re-swipe on the same person replaces the earlier decision (deliberate). `is_match` is true only when the other person already liked you; the conversation is created in the same transaction and both sides get a `match.new` push.\r\n      operationId: swipe\r\n      security: [{ bearerAuth: [] }]\r\n      x-ability: swipe\r\n      x-throttle: swipe\r\n      requestBody:\r\n        required: true\r\n        content:\r\n          application/json:\r\n            schema:\r\n              type: object\r\n              required: [target_id, action]\r\n              properties:\r\n                target_id: { type: string, format: uuid }\r\n                action: { type: string, enum: [like, pass, superlike] }\r\n                source: { type: string, enum: [deck, likes_you, profile], default: deck }\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { $ref: \"#/components/schemas/SwipeResponse\" } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"404\": { $ref: \"#/components/responses/NotFound\" }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n\r\n  # ---- Matches --------------------------------------------------------------------\r\n  /matches:\r\n    get:\r\n      tags: [Matches]\r\n      summary: Your matches\r\n      operationId: listMatches\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      parameters: [{ $ref: \"#/components/parameters/cursor\" }]\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { data: { type: array, items: { $ref: \"#/components/schemas/Match\" } }, meta: { $ref: \"#/components/schemas/CursorMeta\" } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /matches/{match}:\r\n    delete:\r\n      tags: [Matches]\r\n      summary: Unmatch\r\n      description: Ends the match and closes the conversation for both people (MatchActions). The other person gets `403` on their next read or send.\r\n      operationId: unmatch\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      parameters: [{ name: match, in: path, required: true, schema: { type: string, format: uuid } }]\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { message: { type: string } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"404\": { $ref: \"#/components/responses/NotFound\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n\r\n  # ---- Conversations --------------------------------------------------------------\r\n  /conversations:\r\n    get:\r\n      tags: [Conversations]\r\n      summary: Open conversations\r\n      description: Closed threads (block, unmatch) are not listed.\r\n      operationId: listConversations\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      parameters: [{ $ref: \"#/components/parameters/cursor\" }]\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { data: { type: array, items: { $ref: \"#/components/schemas/Conversation\" } }, meta: { $ref: \"#/components/schemas/CursorMeta\" } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /conversations/{conversation}/messages:\r\n    get:\r\n      tags: [Conversations]\r\n      summary: Messages, newest first\r\n      description: The same three guards as sending — participant, thread open, no block either way — so a closed thread is `403` on read as well as on send. The app polls this every six seconds while the thread is on screen; there is no websocket.\r\n      operationId: listMessages\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      parameters:\r\n        - { name: conversation, in: path, required: true, schema: { type: string, format: uuid } }\r\n        - { $ref: \"#/components/parameters/cursor\" }\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { data: { type: array, items: { $ref: \"#/components/schemas/Message\" } }, meta: { $ref: \"#/components/schemas/CursorMeta\" } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"404\": { $ref: \"#/components/responses/NotFound\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n    post:\r\n      tags: [Conversations]\r\n      summary: Send a message\r\n      description: \"`403 forbidden` with the message “This conversation is closed” for a closed thread or a block in either direction — the same refusal on purpose, so a blocked person is not told who blocked them. Links and contact details are flagged on write for the safety team. The recipient gets a `message.new` push.\"\r\n      operationId: sendMessage\r\n      security: [{ bearerAuth: [] }]\r\n      x-ability: message\r\n      x-throttle: message\r\n      parameters: [{ name: conversation, in: path, required: true, schema: { type: string, format: uuid } }]\r\n      requestBody:\r\n        required: true\r\n        content: { application/json: { schema: { type: object, required: [body], properties: { body: { type: string, minLength: 1, maxLength: 2000 } } } } }\r\n      responses:\r\n        \"201\": { description: \"Created\", content: { application/json: { schema: { type: object, properties: { data: { $ref: \"#/components/schemas/Message\" } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"404\": { $ref: \"#/components/responses/NotFound\" }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /conversations/{conversation}/read:\r\n    post:\r\n      tags: [Conversations]\r\n      summary: Mark the thread read\r\n      operationId: markRead\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      parameters: [{ name: conversation, in: path, required: true, schema: { type: string, format: uuid } }]\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { message: { type: string } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"404\": { $ref: \"#/components/responses/NotFound\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n\r\n  # ---- Safety ---------------------------------------------------------------------\r\n  /reports:\r\n    post:\r\n      tags: [Safety]\r\n      summary: Report a member\r\n      description: Becomes (or joins) the reported member's open case in the console, with an SLA set by the category's severity. A message id is kept as evidence only when the reporter is in that conversation and the reported member sent it. Reporting yourself, or the same person twice in 24 hours, is `422`.\r\n      operationId: report\r\n      security: [{ bearerAuth: [] }]\r\n      x-ability: report\r\n      x-throttle: report\r\n      requestBody:\r\n        required: true\r\n        content:\r\n          application/json:\r\n            schema:\r\n              type: object\r\n              required: [reported_id, category]\r\n              properties:\r\n                reported_id: { type: string, format: uuid }\r\n                category: { $ref: \"#/components/schemas/ReportCategory\" }\r\n                description: { type: [string, \"null\"], maxLength: 1000 }\r\n                message_id: { type: [string, \"null\"], format: uuid }\r\n                block: { type: boolean, default: false, description: \"Also block them.\" }\r\n      responses:\r\n        \"201\": { description: \"Filed\", content: { application/json: { schema: { type: object, properties: { data: { type: object, properties: { id: { type: string, format: uuid }, case_opened: { type: boolean } } } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"404\": { $ref: \"#/components/responses/NotFound\" }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /blocks:\r\n    get:\r\n      tags: [Safety]\r\n      summary: People you blocked\r\n      operationId: listBlocks\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { data: { type: array, items: { $ref: \"#/components/schemas/Person\" } } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n    post:\r\n      tags: [Safety]\r\n      summary: Block a member\r\n      description: Closes any conversation between you, removes you from each other's decks, and is never disclosed to them.\r\n      operationId: block\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      requestBody:\r\n        required: true\r\n        content: { application/json: { schema: { type: object, required: [blocked_id], properties: { blocked_id: { type: string, format: uuid }, reason: { type: [string, \"null\"], maxLength: 200 } } } } }\r\n      responses:\r\n        \"201\": { description: \"Blocked\", content: { application/json: { schema: { type: object, properties: { message: { type: string } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"404\": { $ref: \"#/components/responses/NotFound\" }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /blocks/{uuid}:\r\n    delete:\r\n      tags: [Safety]\r\n      summary: Unblock\r\n      description: The closed conversation stays closed.\r\n      operationId: unblock\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      parameters: [{ name: uuid, in: path, required: true, schema: { type: string, format: uuid } }]\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { message: { type: string } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"404\": { $ref: \"#/components/responses/NotFound\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n\r\n  # ---- Phone ----------------------------------------------------------------------\r\n  /phone/send-code:\r\n    post:\r\n      tags: [Phone]\r\n      summary: Text a six-digit code\r\n      description: Six digits, valid ten minutes, one resend a minute. `503 sms_unavailable` when the operator has not configured an SMS gateway — show it, do not retry.\r\n      operationId: sendPhoneCode\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: \"4,10\"\r\n      requestBody:\r\n        required: true\r\n        content: { application/json: { schema: { type: object, required: [phone], properties: { phone: { type: string, minLength: 8, maxLength: 20, example: \"+44 7700 900000\" } } } } }\r\n      responses:\r\n        \"200\": { description: \"Sent\", content: { application/json: { schema: { type: object, properties: { data: { type: object, properties: { expires_at: { type: string, format: date-time } } } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\":\r\n          description: \"`sms_unavailable` (no gateway configured) or `maintenance`.\"\r\n          content: { application/json: { schema: { $ref: \"#/components/schemas/Error\" }, example: { message: \"Phone verification is not available right now.\", code: sms_unavailable } } }\r\n  /phone/verify:\r\n    post:\r\n      tags: [Phone]\r\n      summary: Confirm the code\r\n      description: Five wrong guesses exhaust the code; ask for a new one. Success sets the member's phone as verified.\r\n      operationId: verifyPhone\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: \"10,10\"\r\n      requestBody:\r\n        required: true\r\n        content: { application/json: { schema: { type: object, required: [code], properties: { code: { type: string, pattern: \"^[0-9]{6}$\" } } } } }\r\n      responses:\r\n        \"200\": { description: \"Verified\", content: { application/json: { schema: { type: object, properties: { data: { type: object, properties: { status: { type: string, example: verified } } } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n\r\n  # ---- Devices --------------------------------------------------------------------\r\n  /devices/push-token:\r\n    post:\r\n      tags: [Devices]\r\n      summary: Register a push token\r\n      description: The FCM **device** token (the server sends through Firebase Cloud Messaging HTTP v1). Re-sent whenever the token rotates. No ability is required, so an account under review stays reachable.\r\n      operationId: registerPushToken\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      requestBody:\r\n        required: true\r\n        content:\r\n          application/json:\r\n            schema:\r\n              type: object\r\n              required: [token, platform]\r\n              properties:\r\n                token: { type: string, minLength: 20, maxLength: 512 }\r\n                platform: { type: string, enum: [android, ios, web] }\r\n                label: { type: [string, \"null\"], maxLength: 120 }\r\n                device_fingerprint: { type: [string, \"null\"], maxLength: 255 }\r\n      responses:\r\n        \"201\": { description: \"Registered\", content: { application/json: { schema: { type: object, properties: { data: { type: object, properties: { status: { type: string, example: registered } } } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n    delete:\r\n      tags: [Devices]\r\n      summary: Remove a push token\r\n      description: Called on sign-out.\r\n      operationId: removePushToken\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      requestBody:\r\n        required: true\r\n        content: { application/json: { schema: { type: object, required: [token], properties: { token: { type: string, maxLength: 512 } } } } }\r\n      responses:\r\n        \"200\": { description: \"Removed\", content: { application/json: { schema: { type: object, properties: { data: { type: object, properties: { status: { type: string, example: removed } } } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"422\": { $ref: \"#/components/responses/ValidationFailed\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n\r\n  # ---- Verification ---------------------------------------------------------------\r\n  /verification:\r\n    get:\r\n      tags: [Verification]\r\n      summary: Your latest verification\r\n      description: \"`data` is null when you have never submitted one.\"\r\n      operationId: getVerification\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { data: { oneOf: [{ $ref: \"#/components/schemas/Verification\" }, { type: \"null\" }] } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n    post:\r\n      tags: [Verification]\r\n      summary: Submit a selfie holding the code\r\n      description: Multipart, up to 10 MB. The code must be the one the server issued (ten minutes, single use) or the answer is `422 validation_failed`; after `verification.max_attempts` (3) the answer is `422 verification_attempts_exhausted` and the only way on is support. Accepted submissions go to the standard review queue; a reviewer who suspects a minor escalates to the restricted queue, where approval is not possible. The selfie is stored on a private disk and served to staff only through a signed URL, behind a permission, with every view logged.\r\n      operationId: submitVerification\r\n      security: [{ bearerAuth: [] }]\r\n      x-ability: verify\r\n      x-throttle: verification\r\n      requestBody:\r\n        required: true\r\n        content:\r\n          multipart/form-data:\r\n            schema: { type: object, required: [selfie, gesture_code], properties: { selfie: { type: string, format: binary }, gesture_code: { type: string, minLength: 4, maxLength: 4 } } }\r\n      responses:\r\n        \"202\": { description: \"Accepted for review\", content: { application/json: { schema: { type: object, properties: { data: { $ref: \"#/components/schemas/Verification\" } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"422\":\r\n          description: \"`validation_failed` (wrong or expired code, bad file) or `verification_attempts_exhausted`.\"\r\n          content: { application/json: { schema: { $ref: \"#/components/schemas/Error\" }, example: { message: \"You have used all your verification attempts. Contact support.\", code: verification_attempts_exhausted } } }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n  /verification/gesture:\r\n    get:\r\n      tags: [Verification]\r\n      summary: Get a code to hold up\r\n      description: Four characters, remembered by the server for ten minutes; asking again replaces it.\r\n      operationId: getGestureCode\r\n      security: [{ bearerAuth: [] }]\r\n      x-throttle: api\r\n      responses:\r\n        \"200\": { description: \"OK\", content: { application/json: { schema: { type: object, properties: { gesture_code: { type: string, example: K7QX }, expires_in: { type: integer, description: \"Seconds.\" } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\": { $ref: \"#/components/responses/Maintenance\" }\r\n\r\n  # ---- Premium --------------------------------------------------------------------\r\n  /me/premium/receipt:\r\n    post:\r\n      tags: [Premium]\r\n      summary: Redeem an App Store / Google Play purchase\r\n      description: |\r\n        \"I bought this in the store.\" The transaction is an identifier, never evidence: the server asks Apple or\r\n        Google, honours the store's expiry, and answers with a fresh member. Posting the same transaction again is\r\n        `200` and changes nothing. A sandbox or TestFlight purchase is honoured on a production server. A\r\n        family-shared transaction may be redeemed by each family member. A store purchase never shortens or\r\n        downgrades a plan the member already has from elsewhere. Finish the store transaction only after this\r\n        returns `200` (or `409`); anything else leaves it open for “Restore purchases” to retry.\r\n      operationId: redeemReceipt\r\n      security: [{ bearerAuth: [] }]\r\n      x-ability: profile:write\r\n      x-throttle: receipt\r\n      requestBody:\r\n        required: true\r\n        content:\r\n          application/json:\r\n            schema:\r\n              type: object\r\n              required: [platform, product_id, transaction]\r\n              properties:\r\n                platform: { type: string, enum: [ios, android] }\r\n                product_id: { type: string, maxLength: 120, description: \"Cross-checked only; the store's own product id is what is mapped.\" }\r\n                transaction: { type: string, maxLength: 20000, description: \"iOS: the StoreKit 2 signed transaction (JWS). Android: the purchase token.\" }\r\n      responses:\r\n        \"200\": { description: \"The member, with the plan applied\", content: { application/json: { schema: { type: object, properties: { data: { $ref: \"#/components/schemas/Me\" } } } } } }\r\n        \"401\": { $ref: \"#/components/responses/Unauthenticated\" }\r\n        \"403\": { $ref: \"#/components/responses/Forbidden\" }\r\n        \"409\":\r\n          description: \"`receipt_owned_elsewhere` — a purchased transaction already attached to another member. Finish the store transaction; support can move it.\"\r\n          content: { application/json: { schema: { $ref: \"#/components/schemas/Error\" }, example: { message: \"This purchase is already attached to another account.\", code: receipt_owned_elsewhere } } }\r\n        \"422\":\r\n          description: \"`validation_failed`, `product_unknown` (the store's product id maps to no plan) or `receipt_invalid` (unknown, unpaid, expired, revoked, or for another app).\"\r\n          content: { application/json: { schema: { $ref: \"#/components/schemas/Error\" }, example: { message: \"That purchase could not be verified.\", code: receipt_invalid } } }\r\n        \"429\": { $ref: \"#/components/responses/RateLimited\" }\r\n        \"503\":\r\n          description: \"`store_unavailable` (Apple or Google unreachable, or the store switched off; `Retry-After: 30`) or `maintenance`.\"\r\n          headers: { Retry-After: { schema: { type: integer } } }\r\n          content: { application/json: { schema: { $ref: \"#/components/schemas/Error\" }, example: { message: \"In-app purchases are not available right now.\", code: store_unavailable } } }\r\n";
